class Solution:
    def minRelayPacks(self, L: int, M: List[List[int]], S: int) -> int:
        reach = S
        packs_taken = 0
        next_station = 0
        available = []  # max-heap of packs from stations we have already passed
        while reach < L:
            while next_station < len(M) and M[next_station][0] <= reach:
                heapq.heappush(available, -M[next_station][1])
                next_station += 1
            if not available:
                return -1
            reach += -heapq.heappop(available)
            packs_taken += 1
        return packs_taken

